sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    var bodyData = request.body.data;
    var invoiceId = bodyData.sys_id; 
    var aiResult = bodyData.result;  

    var grInvoice = new GlideRecord('x_1815796_itsmgr_0_invoices');
    if (grInvoice.get(invoiceId)) {
        grInvoice.work_notes = "[ASYNC WEBHOOK] Rezultat primit:\n" + aiResult;
        grInvoice.update();
        response.setStatus(200);
        return {"status": "Success"};
    } else {
        response.setStatus(404);
        return {"error": "Factura nu a fost găsită"};
    }
})(request, response);
